@implementation TMMusicQueuePanel
- (void)viewDidLoad{[super viewDidLoad];self.title=@"播放队列";self.overrideUserInterfaceStyle=UIUserInterfaceStyleDark;self.tableView.backgroundColor=TIOPaper();}
- (NSInteger)tableView:(UITableView *)table numberOfRowsInSection:(NSInteger)section{return TMPlayer.shared.queue.count;}
- (UITableViewCell *)tableView:(UITableView *)table cellForRowAtIndexPath:(NSIndexPath *)index{UITableViewCell *cell=[table dequeueReusableCellWithIdentifier:@"q"]?:[[UITableViewCell alloc]initWithStyle:UITableViewCellStyleSubtitle reuseIdentifier:@"q"];NSDictionary *song=TMPlayer.shared.queue[index.row];cell.textLabel.text=song[@"name"];cell.detailTextLabel.text=song[@"artist"];cell.accessoryType=[song[@"id"]isEqual:TMPlayer.shared.song[@"id"]]?UITableViewCellAccessoryCheckmark:UITableViewCellAccessoryNone;cell.tintColor=TIOAccent();return cell;}
- (void)tableView:(UITableView *)table didSelectRowAtIndexPath:(NSIndexPath *)index{NSArray *queue=TMPlayer.shared.queue;if(index.row<queue.count)[TMPlayer.shared playSong:queue[index.row] queue:queue];[self.navigationController popViewControllerAnimated:YES];}
@end
