 __weak typeof(self) weak=self;[[TMMusicAPI shared]request:@"/api/login/qrcode/unikey" payload:@{@"type":@3} eapi:YES done:^(NSDictionary *j,NSString *error){TMLoginPanel *s=weak;if(!s)return;id key=j[@"unikey"];if(![key isKindOfClass:NSString.class]&&[j[@"data"]isKindOfClass:NSDictionary.class])key=j[@"data"][@"unikey"];if(error||![key isKindOfClass:NSString.class]){s.note.text=error?:@"二维码获取失败，返回重试";return;}s.key=key;s.expiry=[NSDate dateWithTimeIntervalSinceNow:120];NSString *url=[@"https://music.163.com/login?codekey=" stringByAppendingString:[key stringByAddingPercentEncodingWithAllowedCharacters:NSCharacterSet.URLQueryAllowedCharacterSet]];CIFilter *f=[CIFilter filterWithName:@"CIQRCodeGenerator"];[f setValue:[url dataUsingEncoding:NSUTF8StringEncoding] forKey:@"inputMessage"];CIImage *image=[f.outputImage imageByApplyingTransform:CGAffineTransformMakeScale(8,8)];CGImageRef cg=[[CIContext contextWithOptions:nil]createCGImage:image fromRect:image.extent];if(cg){s.qr.image=[UIImage imageWithCGImage:cg];CGImageRelease(cg);}s.note.text=@"请用网易云音乐扫码确认\n二维码两分钟有效；不会读取你的密码。";s.timer=[NSTimer scheduledTimerWithTimeInterval:3 repeats:YES block:^(NSTimer *t){[weak check];}];}];
