static UILabel *Label(CGFloat size,UIFontWeight weight){UILabel *l=[UILabel new];l.font=[[UIFontMetrics metricsForTextStyle:UIFontTextStyleBody] scaledFontForFont:[UIFont systemFontOfSize:size weight:weight]];l.adjustsFontForContentSizeCategory=YES;l.textColor=UIColor.labelColor;l.numberOfLines=0;return l;}
