- (void)login{UIAlertController *a=[UIAlertController alertControllerWithTitle:@"网易云账号" message:TMMusicAPI.shared.hasLogin?@"登录态保存在本机钥匙串。账号有效性以音乐库刷新结果为准。":@"登录后可查看我喜欢、最近播放和歌单。Cookie 不会上传到 Turbo IO 服务器。" preferredStyle:UIAlertControllerStyleActionSheet];__weak typeof(self) weak=self;
 [a addAction:[UIAlertAction actionWithTitle:@"导入自己的 Cookie" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){[weak importCookie];}]];
 [a addAction:[UIAlertAction actionWithTitle:@"二维码登录" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){[weak.navigationController pushViewController:[TMLoginPanel new] animated:YES];}]];
 if(TMMusicAPI.shared.hasLogin)[a addAction:[UIAlertAction actionWithTitle:@"退出并清除音乐记忆" style:UIAlertActionStyleDestructive handler:^(UIAlertAction *x){[TMPlayer.shared play:NO];[TMMusicAPI.shared logout];}]];
 [a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];a.popoverPresentationController.barButtonItem=self.navigationItem.rightBarButtonItems.lastObject;[self presentViewController:a animated:YES completion:nil];}
- (void)importCookie{UIAlertController *a=[UIAlertController alertControllerWithTitle:@"导入本机登录态" message:@"只粘贴自己的 MUSIC_U=…; __csrf=…。先验证再保存，失败不会覆盖原账号。请勿把凭据发给他人。" preferredStyle:UIAlertControllerStyleAlert];[a addTextFieldWithConfigurationHandler:^(UITextField *f){f.placeholder=@"MUSIC_U=…; __csrf=…";f.secureTextEntry=YES;f.autocorrectionType=UITextAutocorrectionTypeNo;f.autocapitalizationType=UITextAutocapitalizationTypeNone;f.textContentType=nil;}];__weak typeof(self) weak=self;
 [a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:^(UIAlertAction *x){a.textFields.firstObject.text=@"";}]];
 [a addAction:[UIAlertAction actionWithTitle:@"验证并保存" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){NSString *cookie=a.textFields.firstObject.text;a.textFields.firstObject.text=@"";weak.navigationItem.prompt=@"正在验证登录态…";[TMMusicAPI.shared validateAndImport:cookie done:^(BOOL ok,NSString *message){TMMusicPanel *s=weak;if(!s)return;s.navigationItem.prompt=nil;UIAlertController *r=[UIAlertController alertControllerWithTitle:ok?@"已登录":@"未导入" message:message preferredStyle:UIAlertControllerStyleAlert];[r addAction:[UIAlertAction actionWithTitle:@"完成" style:UIAlertActionStyleCancel handler:nil]];if(!s.presentedViewController)[s presentViewController:r animated:YES completion:nil];}];}]];[self presentViewController:a animated:YES completion:nil];}
- (void)playlist{UIAlertController *a=[UIAlertController alertControllerWithTitle:@"打开网易云歌单" message:@"输入歌单 ID（分享链接中的 id）。当前账号无权访问的内容不会绕过限制。" preferredStyle:UIAlertControllerStyleAlert];[a addTextFieldWithConfigurationHandler:^(UITextField *f){f.placeholder=@"歌单 ID";f.keyboardType=UIKeyboardTypeNumberPad;}];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[a addAction:[UIAlertAction actionWithTitle:@"打开" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){long long n=a.textFields.firstObject.text.longLongValue;if(n<=0)return;[self load:@"/api/v6/playlist/detail" payload:@{@"id":@(n),@"n":@100,@"s":@8} eapi:YES];}]];[self presentViewController:a animated:YES completion:nil];}
- (void)searchBarSearchButtonClicked:(UISearchBar *)searchBar{[searchBar resignFirstResponder];NSString *q=[searchBar.text stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet];if(!q.length)return;_libraryKind=@"search";_libraryQuery=q;_libraryTabs.selectedSegmentIndex=UISegmentedControlNoSegment;[self refreshLibrary];}
- (void)load:(NSString *)path payload:(NSDictionary *)payload eapi:(BOOL)eapi{_libraryKind=@"playlist";_libraryQuery=[payload[@"id"]description];_libraryTabs.selectedSegmentIndex=2;_pageMode.selectedSegmentIndex=1;[self refreshLibrary];[self pageModeChanged];}
- (void)libraryTabChanged{_libraryKind=@[@"liked",@"recent",@"playlists"][_libraryTabs.selectedSegmentIndex];_libraryQuery=@"";[self refreshLibrary];}
- (void)accountChanged{++_searchTicket;_loading=NO;_results=nil;[_covers removeAllObjects];_libraryKind=@"liked";_libraryQuery=@"";_libraryTabs.selectedSegmentIndex=0;if(_pageMode.selectedSegmentIndex==1)[self refreshLibrary];else [self.tableView reloadData];}
- (void)refreshLibrary{++_searchTicket;_loading=NO;_results=@[];_nextOffset=0;_total=0;_failed=NO;[self fetchPage];}
- (void)loadMore{if(_failed&&_nextOffset==0)[self refreshLibrary];else [self fetchPage];}
- (void)updateFooter{_loadMoreButton.enabled=!_loading;[_loadMoreButton setTitle:_loading?@"加载中…":_failed?@"重试":@"加载更多" forState:UIControlStateNormal];self.tableView.tableFooterView=_pageMode.selectedSegmentIndex==1&&(_failed||(_nextOffset<_total&&_nextOffset<1000))?_loadMoreButton:nil;}
- (void)fetchPage{if(_loading)return;
 if(!TMMusicAPI.shared.hasLogin&&![_libraryKind isEqual:@"search"]&&![_libraryKind isEqual:@"playlist"]){_libraryNote.text=@"登录后查看你的音乐。点右上角账号，可导入 Cookie 或扫码登录；搜索仍可使用。";[self.refreshControl endRefreshing];[self updateFooter];[self.tableView reloadData];[self.view setNeedsLayout];return;}
 _loading=YES;_failed=NO;NSUInteger ticket=++_searchTicket,offset=_nextOffset;NSString *kind=[_libraryKind copy];NSString *title=@{@"liked":@"我喜欢的音乐",@"recent":@"账号最近播放",@"playlists":@"我的歌单",@"playlist":@"歌单歌曲",@"search":@"搜索结果"}[kind]?:@"音乐";
 _libraryNote.text=[title stringByAppendingString:@" · 正在加载…"];[self updateFooter];[self.tableView reloadData];[self.view setNeedsLayout];
 [NSUserDefaults.standardUserDefaults setObject:kind forKey:@"TurboMusicLibraryKindV2"];[NSUserDefaults.standardUserDefaults setObject:_libraryQuery?:@"" forKey:@"TurboMusicLibraryQueryV2"];
 __weak typeof(self) weak=self;[_library fetch:kind query:_libraryQuery?:@"" offset:offset done:^(NSArray *rows,NSUInteger total,NSString *error){TMMusicPanel *s=weak;if(!s||ticket!=s.searchTicket)return;s.loading=NO;[s.refreshControl endRefreshing];s.failed=error!=nil;
  if(error)s.libraryNote.text=[title stringByAppendingFormat:@" · %@",error];else{NSMutableArray *combined=[s.results mutableCopy]?:[NSMutableArray new];NSMutableSet *ids=[NSMutableSet new];for(NSDictionary *r in combined)[ids addObject:r[@"id"]];for(NSDictionary *r in rows)if(![ids containsObject:r[@"id"]]){[combined addObject:r];[ids addObject:r[@"id"]];}s.results=combined;s.total=total;s.nextOffset=offset+50;
   s.libraryNote.text=combined.count?[NSString stringWithFormat:@"%@ · %lu / %lu %@%@",title,(unsigned long)combined.count,(unsigned long)total,[kind isEqual:@"playlists"]?@"个":@"首",[kind isEqual:@"recent"]?@"\n来自账号记录，可能有同步延迟":@""]:[title stringByAppendingString:@" · 暂无内容"];if(s.nextOffset>=1000&&total>1000)s.libraryNote.text=[s.libraryNote.text stringByAppendingString:@"\n当前展示上限 1000 项，可通过搜索定位歌曲"];}
  [s updateFooter];[s.tableView reloadData];[s.view setNeedsLayout];
 }];
}
- (NSInteger)tableView:(UITableView *)tableView numberOfRowsInSection:(NSInteger)section{return _pageMode.selectedSegmentIndex==1?_results.count:0;}
- (UITableViewCell *)tableView:(UITableView *)tableView cellForRowAtIndexPath:(NSIndexPath *)ip{UITableViewCell *c=[tableView dequeueReusableCellWithIdentifier:@"song"]?:[[UITableViewCell alloc]initWithStyle:UITableViewCellStyleSubtitle reuseIdentifier:@"song"];NSDictionary *song=_results[ip.row];UIListContentConfiguration *content=[c defaultContentConfiguration];content.text=song[@"name"];content.secondaryText=song[@"artist"];content.textProperties.numberOfLines=1;content.secondaryTextProperties.numberOfLines=1;content.textProperties.font=[UIFont systemFontOfSize:16 weight:UIFontWeightMedium];content.secondaryTextProperties.color=UIColor.secondaryLabelColor;NSString *cover=song[@"cover"];UIImage *cached=[_covers objectForKey:cover?:@""];content.image=cached?:[UIImage systemImageNamed:[_libraryKind isEqual:@"playlists"]?@"music.note.list":@"music.note"];content.imageProperties.maximumSize=CGSizeMake(44,44);content.imageProperties.reservedLayoutSize=CGSizeMake(44,44);content.imageProperties.cornerRadius=8;content.imageProperties.tintColor=TIOAccent();c.contentConfiguration=content;c.accessoryType=UITableViewCellAccessoryDisclosureIndicator;c.backgroundColor=[TIOInk()colorWithAlphaComponent:.045];c.accessibilityIdentifier=[@"music-song-" stringByAppendingString:[song[@"id"]description]];
 if(!cached&&cover.length){NSURLComponents *url=[NSURLComponents componentsWithString:cover];NSString *host=url.host.lowercaseString;if(([host hasSuffix:@".126.net"]||[host hasSuffix:@".163.com"])&&!url.user&&!url.password&&([url.scheme isEqual:@"http"]||[url.scheme isEqual:@"https"])){url.scheme=@"https";url.query=@"param=96y96";__weak typeof(self) weak=self;__weak UITableViewCell *cell=c;NSString *identity=c.accessibilityIdentifier;
  [[NSURLSession.sharedSession dataTaskWithURL:url.URL completionHandler:^(NSData *data,NSURLResponse *response,NSError *error){if(error||data.length>2*1024*1024)return;CGImageSourceRef src=CGImageSourceCreateWithData((__bridge CFDataRef)data,NULL);if(!src)return;CGImageRef cg=CGImageSourceCreateThumbnailAtIndex(src,0,(__bridge CFDictionaryRef)@{(__bridge id)kCGImageSourceCreateThumbnailFromImageAlways:@YES,(__bridge id)kCGImageSourceThumbnailMaxPixelSize:@96});CFRelease(src);UIImage *im=cg?[UIImage imageWithCGImage:cg]:nil;if(cg)CGImageRelease(cg);if(!im)return;dispatch_async(dispatch_get_main_queue(),^{TMMusicPanel *s=weak;if(!s)return;[s.covers setObject:im forKey:cover cost:96*96*4];UITableViewCell *current=cell;if([current.accessibilityIdentifier isEqual:identity]){UIListContentConfiguration *config=[(UIListContentConfiguration *)current.contentConfiguration copy];config.image=im;current.contentConfiguration=config;}});} ]resume];}}
 return c;}
- (CGFloat)tableView:(UITableView *)tableView heightForRowAtIndexPath:(NSIndexPath *)ip{return 64;}
- (void)tableView:(UITableView *)tableView didSelectRowAtIndexPath:(NSIndexPath *)ip{[tableView deselectRowAtIndexPath:ip animated:YES];if(ip.row>=_results.count)return;NSDictionary *song=_results[ip.row];if([_libraryKind isEqual:@"playlists"]){_libraryKind=@"playlist";_libraryQuery=[song[@"id"]description];[self refreshLibrary];return;}[TMPlayer.shared playSong:song queue:_results];self.pageMode.selectedSegmentIndex=0;[self pageModeChanged];[tableView setContentOffset:CGPointMake(0,-tableView.adjustedContentInset.top) animated:YES];}
@end
UIViewController *TMMusicController(void){return [[TMMusicPanel alloc]initWithStyle:UITableViewStyleInsetGrouped];}
